import {test} from 'node:test';import assert from 'node:assert/strict';import {DatabaseSync} from 'node:sqlite';import {readFileSync} from 'node:fs';import {handleFantasy as realFantasy} from './fantasy-service.mjs';import config from './fantasy-config.cjs';import policy from './fantasy-leagues.cjs';import catalog from './fantasy-players.json' with {type:'json'};
const handleFantasy=(r,e,d={})=>realFantasy(r,e,{getTeams:async()=>['680163'],adminAuthorize:d.authorize|| (async()=>{throw Object.assign(Error('No admin'),{status:403})}),...d});
const base='https://club.test/api/fantasy',owner={authorize:async()=> 'owner-uid'},other={authorize:async()=> 'second-uid'};
const request=(path,body)=>new Request(base+path,{method:body?'POST':'GET',...(body?{body:JSON.stringify(body)}:{})});
async function fixtureLeague(e,uid,value){const id=crypto.randomUUID(),teamId=value.teamId||value.pool?.teamId||'680163',settings=value.mode==='custom'?value.settings:policy.classicSettings;await e.CHAT_DB.batch([e.CHAT_DB.prepare('INSERT INTO fantasy_leagues VALUES(?,?,?,?,?,?,?,?,?,?)').bind(id,uid,value.requestId,'fixture',value.name,value.mode,JSON.stringify({type:'club'}),JSON.stringify(settings),crypto.randomUUID().replace(/[^A-HJ-NP-Z2-9]/g,'').padEnd(8,'A').slice(0,8),Date.parse('2026-11-13T12:00:00Z')),e.CHAT_DB.prepare('INSERT INTO fantasy_league_groups VALUES(?,?)').bind(id,teamId),e.CHAT_DB.prepare('INSERT INTO fantasy_members VALUES(?,?,?,?)').bind(id,uid,value.nickname,Date.parse('2026-11-13T12:00:00Z'))]);return (await handleFantasy(request('/leagues/'+id),e,{authorize:async()=>uid})).json()};
const classic=(id='request-0001')=>({requestId:id,mode:'classic',name:'Liga Aficionado',nickname:'Creador',pool:{type:'team',teamId:'680163'}});
function env(t){const sql=new DatabaseSync(':memory:');sql.exec(readFileSync('fantasy-schema.sql','utf8'));sql.exec(readFileSync('social-schema.sql','utf8'));sql.exec(readFileSync('fantasy-club-schema.sql','utf8'));sql.exec(readFileSync('fantasy-actas-schema.sql','utf8'));sql.exec(readFileSync('fantasy-access-schema.sql','utf8'));sql.exec(readFileSync('fantasy-game-schema.sql','utf8'));sql.exec(readFileSync('fantasy-lineup-lock-schema.sql','utf8'));sql.exec(readFileSync('fantasy-rewards-schema.sql','utf8'));sql.exec(readFileSync('fantasy-auction-schema.sql','utf8'));sql.exec(readFileSync('fantasy-sales-schema.sql','utf8'));sql.exec(readFileSync('fantasy-resale-schema.sql','utf8'));sql.exec(readFileSync('fantasy-clause-schema.sql','utf8'));sql.exec(readFileSync('fantasy-manager-listings-schema.sql','utf8'));sql.exec(readFileSync('fantasy-player-positions-schema.sql','utf8'));sql.exec(readFileSync('fantasy-stat-corrections-schema.sql','utf8'));sql.exec(readFileSync('fantasy-league-admin-history-schema.sql','utf8'));sql.exec(readFileSync('fantasy-point-history-schema.sql','utf8'));sql.prepare('UPDATE fantasy_economy_policy SET settings_json=?').run(JSON.stringify({weeklyIncomeCents:200,fromWeek:0,prizesFromWeek:2967}));sql.prepare('UPDATE fantasy_salary_policy SET settings_json=?,revision=0').run(JSON.stringify({baseCents:null,voteCents:0,winCents:0,drawCents:0,extraTeamCents:0}));sql.exec("DROP TRIGGER IF EXISTS fantasy_roster_min;DROP TRIGGER IF EXISTS fantasy_roster_max;CREATE TRIGGER IF NOT EXISTS legacy_fixture_manager AFTER INSERT ON fantasy_members BEGIN INSERT OR IGNORE INTO fantasy_managers VALUES(NEW.league_id,NEW.uid,'legacy-fixture',1,1,1,1);END;");sql.exec('UPDATE fantasy_access_settings SET disabled=0');t.after(()=>sql.close());const prepare=(q,args=[])=>({bind:(...v)=>prepare(q,v),first:async()=>sql.prepare(q).get(...args),all:async()=>({results:sql.prepare(q).all(...args)}),run:()=>({meta:{changes:Number(sql.prepare(q).run(...args).changes)}})});return {sql,env:{CHAT_DB:{prepare,batch:async statements=>{sql.exec('BEGIN');try{const rows=[];for(const s of statements)rows.push(s.run());sql.exec('COMMIT');return rows}catch(e){sql.exec('ROLLBACK');throw e}}}}}}
test('every Fantasy route requires authentication, and private preview is not cached',async()=>{assert.equal((await handleFantasy(request('/preview'),{})).status,401);for(const path of ['/leagues','/join','/leagues/fake/players'])assert.equal((await handleFantasy(request(path),{},{authorize:async()=>{throw Object.assign(Error('Solo admin'),{status:403})}})).status,403);const r=await handleFantasy(request('/preview'),{},owner);assert.equal(r.headers.get('Cache-Control'),'no-store');assert.deepEqual((await r.json()).rules.points,config.rules.points);assert.equal(await handleFantasy(new Request('https://club.test/api/news'),{}),null)});
test('price criteria reward goals and wins; top players cost more, scope excludes other teams and data uncertainty is visible',()=>{const prices=policy.pricePlayers([{id:'a',name:'Top',goals:10,wins:7,played:9,cleanSheets:0,red:0},{id:'b',name:'Base',goals:0,wins:0,played:0,cleanSheets:0,red:0}]);assert(prices[0].price>prices[1].price);assert(prices[0].top);assert(prices.every(p=>p.price>=7.02&&p.price<=60.84));const team=catalog.teams.find(t=>t.id==='680163'),rows=policy.playersForPool(catalog,{type:'team',teamId:team.id});assert(rows.length>=11);assert(rows.every(p=>p.teams.every(t=>t.id===team.id)));assert(rows.some(p=>p.top));assert(rows.every(p=>typeof p.partial==='boolean'))});
test('the 80 percent increase is preserved instead of reducing prices to fit the starting budget',()=>{const c={teams:[{id:'team',category:'Juvenil',players:Array.from({length:11},(_,i)=>({id:String(i),name:'Jugador '+i,goals:30,wins:30,played:30,cleanSheets:0,red:0,partial:false}))}]},p=policy.playersForPool(c,{type:'team',teamId:'team'});assert(p.reduce((n,v)=>n+v.price,0)>40);assert(p.every(p=>p.price>=7.02))});
test('admin prices persist across admins and league scopes, reset restores automatic and stale edits cannot overwrite',async t=>{const {env:e,sql}=env(t),id=catalog.teams.find(t=>t.id==='680163').players[0].id;const get=async()=> (await(await handleFantasy(request('/admin/players?team=680163'),e,owner)).json()).players.find(p=>p.id===id);const initial=await get();assert.equal(initial.priceRevision,0);const edit={playerId:id,price:18.5,revision:0};let r=await handleFantasy(request('/admin/prices',edit),e,owner);assert.equal(r.status,200);assert.equal((await r.json()).revision,1);const current=await get();assert.equal(current.price,18.5);assert.equal(current.automaticPrice,initial.price);assert.equal(current.manualPrice,true);const global=await(await handleFantasy(request('/admin/players'),e,other)).json();assert.equal(global.players.find(p=>p.id===id).price,18.5);assert(!JSON.stringify(global).includes('owner-uid'));assert.equal((await handleFantasy(request('/admin/prices',{...edit,price:20}),e,other)).status,409);const league=await fixtureLeague(e,'owner-uid',classic());assert(league.league);const players=await(await handleFantasy(request('/leagues/'+league.league.id+'/players'),e,owner)).json();assert.equal(players.players.find(p=>p.id===id).price,18.5);r=await handleFantasy(request('/admin/prices',{...edit,price:22,revision:1}),e,other);assert.equal(r.status,200);assert.equal(sql.prepare('SELECT changed_by FROM fantasy_player_cents WHERE player_id=?').get(id).changed_by,'second-uid');r=await handleFantasy(request('/admin/prices',{...edit,price:null,revision:2}),e,owner);assert.equal(r.status,200);const reset=await get();assert.equal(reset.price,initial.price);assert.equal(reset.manualPrice,false);assert.equal(reset.priceRevision,3);assert.equal((await handleFantasy(request('/admin/prices',edit),e,other)).status,409)});
test('price settings reject invalid values, unknown players, stale revisions, foreign origins and nonadmins',async t=>{const {env:e,sql}=env(t),id=catalog.teams[0].players[0].id;for(const price of [0,-1,235,1.255,'5',undefined]){const r=await handleFantasy(request('/admin/prices',{playerId:id,price,revision:0}),e,owner);assert.equal(r.status,400)}assert.equal((await handleFantasy(request('/admin/prices',{playerId:'missing',price:5,revision:0}),e,owner)).status,404);assert.equal((await handleFantasy(request('/admin/prices',{playerId:id,price:5,revision:8}),e,owner)).status,409);for(const path of ['/admin/players','/admin/prices'])assert.equal((await handleFantasy(request(path,path.endsWith('prices')?{playerId:id,price:5,revision:0}:undefined),e,{authorize:async()=>{throw Object.assign(Error('Solo administrador'),{status:403})}})).status,403);const foreign=new Request(base+'/admin/prices',{method:'POST',headers:{Origin:'https://evil.test'},body:JSON.stringify({playerId:id,price:5,revision:0})});assert.equal((await handleFantasy(foreign,e,owner)).status,403);assert.equal(sql.prepare('SELECT COUNT(*) n FROM fantasy_player_prices').get().n,0)});
test('weekly allowance follows Madrid Monday including DST, accumulates offline and never credits a future join',()=>{const settings={budget:40};const start=Date.parse('2026-03-27T12:00:00Z');assert.equal(policy.weeklyBudget(settings,start,Date.parse('2026-03-29T21:59:59Z')).balance,40);assert.equal(policy.weeklyBudget(settings,start,Date.parse('2026-03-29T22:00:00Z')).balance,42);assert.equal(policy.weeklyBudget(settings,start,Date.parse('2026-04-12T22:00:00Z')).balance,46);assert.equal(policy.weeklyBudget(settings,start,start-1000).creditedWeeks,0);const autumn=Date.parse('2026-10-23T12:00:00Z');assert.equal(policy.weeklyBudget(settings,autumn,Date.parse('2026-10-25T22:59:59Z')).balance,40);assert.equal(policy.weeklyBudget(settings,autumn,Date.parse('2026-10-25T23:00:00Z')).balance,42)});
test('each member receives weekly funds from joining; repeated reads and rejoining cannot duplicate or reset them',async t=>{const {env:e,sql}=env(t),start=Date.parse('2026-11-06T12:00:00Z'),later=Date.parse('2026-11-15T23:00:00Z'),opts={...owner,clock:()=>start};const d=await(await handleFantasy(request('/team-league',{teamId:'680163',nickname:'Jugador'}),e,opts)).json();assert.equal(d.league.finance.balance,52);const read=async uid=>(await(await handleFantasy(request('/leagues/'+d.league.id),e,{authorize:async()=>uid,clock:()=>later})).json()).league;assert.equal((await read('owner-uid')).finance.balance,56);assert.equal((await read('owner-uid')).finance.balance,56);const guest={...other,clock:()=>later};await handleFantasy(request('/join',{code:d.league.code,nickname:'Nuevo'}),e,guest);assert.equal((await read('second-uid')).finance.balance,52);await handleFantasy(request('/join',{code:d.league.code,nickname:'Nuevo'}),e,guest);assert.equal(sql.prepare('SELECT joined_at FROM fantasy_members WHERE uid=?').get('second-uid').joined_at,later);const list=await(await handleFantasy(request('/leagues'),e,{...owner,clock:()=>later})).json();assert.equal(list.leagues[0].finance.balance,56);sql.prepare('UPDATE fantasy_leagues SET settings_json=json_set(settings_json,\'$.budget\',100)').run();assert.equal((await read('owner-uid')).finance.initial,52)});
const marketBody=(listing,suffix='market-buy-0001',catalogVersion=catalog.version+'-actas-30-v2')=>({listingId:listing.listingId,price:listing.price,revision:listing.priceRevision,catalogVersion,requestId:suffix});
async function marketFixture(t,{classicMode=false}={}){const {env:e,sql}=env(t);let now=Date.parse('2026-11-13T12:00:00Z');const call=(uid,path,value)=>handleFantasy(request(path,value),e,{authorize:async()=>uid,clock:()=>now});const value=classicMode?classic('market-classic'):({...classic('market-custom'),mode:'custom',settings:{...policy.classicSettings,budget:200,transfers:10}});const created=await fixtureLeague(e,'owner',value);assert(created.league);const id=created.league.id,prefix='/leagues/'+id;const snapshot=async uid=>{const r=await call(uid,prefix+'/market');assert.equal(r.status,200,JSON.stringify(await r.clone().json()));return r.json()};return{e,sql,id,prefix,call,snapshot,created,advance:days=>now+=days*86400000,setTime:v=>now=Date.parse(v),join:uid=>call(uid,'/join',{code:created.league.code,nickname:'Equipo '+uid})}}
test('leagues are restricted to approved teammates, market covers the club, and a code or forged team cannot bypass membership',async t=>{const {env:e,sql}=env(t),teamsByUid={'owner-uid':['680163'],'second-uid':['10659267']},depsFor=uid=>({authorize:async()=>uid,getTeams:async(r,target)=>teamsByUid[target]||[]});const created=await fixtureLeague(e,'owner-uid',classic('cohort-league'));assert.equal(created.league.teamId,'680163');assert.equal(created.league.pool.type,'club');const id=created.league.id;const all=await(await handleFantasy(request('/leagues/'+id+'/players'),e,depsFor('owner-uid'))).json();assert(all.players.length>100);assert(all.players.some(p=>!p.teams.some(t=>t.id==='680163')));assert.equal((await handleFantasy(request('/team-league',{teamId:'10659267',nickname:'Intruso',role:'admin'}),e,depsFor('owner-uid'))).status,403);assert.equal((await handleFantasy(request('/join',{code:created.league.code,nickname:'Intruso',teamId:'680163'}),e,depsFor('second-uid'))).status,403);assert.equal(sql.prepare('SELECT COUNT(*) n FROM fantasy_members').get().n,1);teamsByUid['second-uid']=['680163'];assert.equal((await handleFantasy(request('/join',{code:created.league.code,nickname:'Compañero'}),e,depsFor('second-uid'))).status,200);teamsByUid['second-uid']=['10659267'];assert.equal((await handleFantasy(request('/leagues/'+id+'/market'),e,depsFor('second-uid'))).status,403);assert.deepEqual((await(await handleFantasy(request('/leagues'),e,depsFor('second-uid'))).json()).leagues,[])});
test('automatic prices include both increases without compounding, and live player and goalkeeper voting affects valuation',async t=>{const basePlayer={id:'base',name:'Base',goals:0,wins:0,played:0,cleanSheets:0,red:0},top={...basePlayer,id:'top',name:'Top',goals:20};const first=policy.pricePlayers([basePlayer,top]);assert.equal(first.find(p=>p.id==='base').price,7.02);assert.deepEqual(policy.pricePlayers([basePlayer,top]),first);const voted=policy.pricePlayers([{...basePlayer,votePoints:3},top]);assert(voted.find(p=>p.id==='base').price>7.02);const {env:e,sql}=env(t),d=await fixtureLeague(e,'owner-uid',classic()),path='/leagues/'+d.league.id+'/players',initial=(await(await handleFantasy(request(path),e,owner)).json()).players,p=initial.find(p=>p.position==='Portero');assert(p);for(const [category,points] of [['player',3],['goalkeeper',2]])sql.prepare('INSERT INTO social_ballots VALUES(?,?,?,?,?,?)').run('2026-27',category,'voter',points,p.id,1);const after=(await(await handleFantasy(request(path),e,owner)).json()).players.find(row=>row.id===p.id);assert.equal(after.votePoints,5);assert(after.price>p.price);const admin=(await(await handleFantasy(request('/admin/players?team='+p.teamId),e,owner)).json()).players.find(row=>row.id===p.id);assert.equal(admin.automaticPrice,after.price)});
test('migration raises prior manual values once and preserves cash, purchases and existing league groups',t=>{const sql=new DatabaseSync(':memory:');t.after(()=>sql.close());sql.exec(readFileSync('fantasy-schema.sql','utf8'));sql.prepare('INSERT INTO fantasy_leagues VALUES(?,?,?,?,?,?,?,?,?,?)').run('league','owner','request-key','hash','Liga','classic',JSON.stringify({type:'team',teamId:'680163'}),JSON.stringify(policy.classicSettings),'ABCD2345',1);sql.prepare('INSERT INTO fantasy_members VALUES(?,?,?,?)').run('league','owner','Owner',1);sql.prepare('INSERT INTO fantasy_player_prices VALUES(?,?,?,?,?)').run('pid',7.5,1,1,'admin');sql.prepare('INSERT INTO fantasy_market_listings VALUES(?,?,?,?,?,NULL)').run('listing','league','pid',100,0);sql.prepare('INSERT INTO fantasy_trades VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').run('trade','league','owner',null,null,'pid',15,'request-trade',null,'listing',100,1,80,1,1);const before=sql.prepare('SELECT amount_units FROM fantasy_trades').get().amount_units;sql.exec(readFileSync('fantasy-club-schema.sql','utf8'));sql.exec(readFileSync('fantasy-club-schema.sql','utf8'));assert.equal(sql.prepare('SELECT price_tenths FROM fantasy_player_values').get().price_tenths,135);assert.equal(sql.prepare('SELECT delta_tenths FROM fantasy_wallet_values').get().delta_tenths,-75);assert.equal(sql.prepare('SELECT amount_units FROM fantasy_trades').get().amount_units,before);assert.equal(sql.prepare('SELECT team_id FROM fantasy_league_groups').get().team_id,'680163');assert.equal(sql.prepare('SELECT price_units FROM fantasy_roster').get().price_units,15)});
