test('manual league creation is closed by default; automatic team entry is idempotent, cannot forge membership and nonadmin players can play',async t=>{const {env:e,sql}=env(t),denied=async()=>{throw Object.assign(Error('No admin'),{status:403})},opts={authorize:async()=> 'player',adminAuthorize:denied};assert.equal((await handleFantasy(request('/leagues',classic()),e,opts)).status,403);const create=()=>handleFantasy(request('/team-league',{teamId:'680163',nickname:'Jugador'}),e,opts);const responses=await Promise.all([create(),create()]);for(const r of responses)assert.equal(r.status,200,JSON.stringify(await r.clone().json()));const d=await responses[0].json();assert.equal(d.league.settings.budget,52);assert.equal(d.league.finance.balance,52);assert.equal(d.league.isOwner,false);assert.equal(sql.prepare('SELECT COUNT(*) n FROM fantasy_leagues').get().n,1);assert.equal(sql.prepare('SELECT COUNT(*) n FROM fantasy_members').get().n,1);assert.equal((await handleFantasy(request('/leagues/'+d.league.id+'/market'),e,opts)).status,200);for(const path of ['/admin/players','/admin/prices'])assert.equal((await handleFantasy(request(path,path.endsWith('prices')?{price:1}:undefined),e,opts)).status,403);assert.equal((await handleFantasy(request('/team-league',{teamId:'680163',nickname:'Fan',role:'player'}),e,{...opts,getTeams:async()=>[]})).status,403);const preview=await(await handleFantasy(request('/preview'),e,{...opts,getTeams:async()=>[]})).json();assert.equal(preview.canPlay,false);assert.equal(preview.features.leagues,false)});
